mapper.select:
SELECT DISTINCT event.event_name FROM bi_tracking_change_record change_record JOIN bi_tracking_event event ON event.event_id = change_record.event_id WHERE change_record.approval_status = '1' AND change_record.change_type IN ('REGISTER', 'UPDATE') AND change_record.approve_time <= #{endTime}
AND change_record.approve_time > #{startTime}
ORDER BY event.event_name

SELECT 
FROM bi_tracking_quality_issue

    AND region_id = #{regionId}

        AND event_name LIKE CONCAT('%', #{eventName}, '%')


        AND issue_type = #{issueType}


        AND severity = #{severity}


        AND status = #{status}


        AND assignee LIKE CONCAT('%', #{assignee}, '%')


ORDER BY FIELD(status, '0', '1', '2', '3'),
         FIELD(severity, 'HIGH', 'MEDIUM', 'LOW'), last_detect_time DESC

SELECT 
FROM bi_tracking_quality_issue
WHERE issue_id = #{issueId}
  AND region_id = #{regionId}
